    /**
     * Load the original prop models and scatter them through the city: street
     * lamps along the roads, kiosks at some side-street mouths, and
     * flying-car traffic above the streets. Skipped (with a clean fallback to
     * the procedural scene) when no model base URL is configured or a load
     * fails.
     */
    Cyberspace.prototype.buildProps = function() {
        if (!this.config.modelsbaseurl) {
            return;
        }
        var self = this;
        var load = function(name, onReady) {
            self.loadProp(name).then(function(tpl) {
                // Cache the template so the in-view placer can clone it, and
                // build any teacher-placed props of this type.
                self.propTemplates[name] = tpl;
                if (onReady) {
                    onReady(tpl);
                }
                self.buildPlacedObjectsOfType(name, tpl);
                // Refresh the wet-street reflection so it shows the props.
                self.scheduleWetCapture();
                return null;
            }).catch(function(e) {
                if (window.console) {
                    window.console.warn('format_mnemo: prop ' + name + ' unavailable', e);
                }
            });
        };

        load('lamp', function(tpl) {
            self.placeLampSlots(tpl);
        });
        load('kiosk', function(tpl) {
            self.scatterKiosks(tpl);
        });
        // The vehicle template is needed for teacher-placed vehicles (and the
        // placer); flying traffic is built separately from the admin-authored
        // car types below, which may use several different models.
        load('av');

        // Load templates for any prop beyond the built-in four that is already
        // placed in this course, so every viewer sees it. load() caches each
        // template and builds its placed objects. Palette-only props (that an
        // editor might place but has not yet) are loaded lazily when their
        // palette button is selected - see buildPlacer/ensurePropTemplate - so
        // a large uploaded asset pack does not download and parse on every
        // teacher page view.
        // Null-prototype maps so a prop literally named "constructor",
        // "toString" or "__proto__" cannot collide with an inherited property.
        var known = Object.create(null);
        known.lamp = true;
        known.kiosk = true;
        known.av = true;
        var extra = Object.create(null);
        this.placedObjects.forEach(function(p) {
            // Procedural props (the energy barriers) have no model to load; they
            // are built directly from code below.
            if (!known[p.type] && !self.isProceduralProp(p.type)) {
                extra[p.type] = true;
            }
        });
        Object.keys(extra).forEach(function(name) {
            load(name);
        });

        // Build any placed procedural props (energy barriers / arches).
        this.buildPlacedProceduralProps();

        this.buildTraffic();
    };

    /**
     * Ensure a prop's model template is loaded (for the in-view placer): load
     * it once on demand, cache it, and build any already-placed objects of that
     * type. A no-op when the template is already loaded or in flight. Used to
     * lazily fetch a palette prop only when its button is selected, rather than
     * downloading the whole palette up front.
     *
     * @param {String} name The prop model base name.
     */
    Cyberspace.prototype.ensurePropTemplate = function(name) {
        var self = this;
        // Procedural props (energy barriers) have no model to fetch.
        if (!name || this.propTemplates[name] || this.isProceduralProp(name)) {
            return;
        }
        this.propLoading = this.propLoading || {};
        if (this.propLoading[name]) {
            return;
        }
        this.propLoading[name] = true;
        this.loadProp(name).then(function(tpl) {
            self.propTemplates[name] = tpl;
            self.buildPlacedObjectsOfType(name, tpl);
            return null;
        }).catch(function(e) {
            if (window.console) {
                window.console.warn('format_mnemo: prop ' + name + ' unavailable', e);
            }
        });
    };

    /**
     * The default resting height for a placed prop of a given type: props sit
     * on the ground, but a placed vehicle hovers above its grid square like the
     * flying traffic.
     *
     * @param {String} type The prop model name (lamp, kiosk, av).
     * @return {Number} The world-y to place it at.
     */
    Cyberspace.prototype.placedBaseY = function(type) {
        return type === 'av' ? 6 : 0;
    };

    /**
     * A human label for a placed prop type, from the localised placer strings.
     *
     * @param {String} type The prop model name.
     * @return {String} The label.
     */
    Cyberspace.prototype.propLabel = function(type) {
        var s = this.config.strings || {};
        var labels = {
            lamp: s.placelamp || 'Street lamp',
            kiosk: s.placekiosk || 'Kiosk',
            av: s.placevehicle || 'Vehicle',
            echeckpoint: s.placecheckpoint || 'Energy checkpoint',
            earch: s.placearch || 'Energy arch'
        };
        if (labels[type]) {
            return labels[type];
        }
        // An uploaded prop is labelled by its file name (via the server palette).
        var list = this.config.placerprops || [];
        for (var i = 0; i < list.length; i++) {
            if (list[i].key === type) {
                return list[i].label;
            }
        }
        return type;
    };

    /**
     * Build every teacher-placed prop of a given type from its template,
     * registering each as an editable keyed placed:&lt;id&gt; so its transform
     * and brightness persist and it can be selected, moved and deleted.
     *
     * @param {String} type The prop model name.
     * @param {Object} tpl The loaded template group.
     */
    Cyberspace.prototype.buildPlacedObjectsOfType = function(type, tpl) {
        var y = this.placedBaseY(type);
        for (var i = 0; i < this.placedObjects.length; i++) {
            var p = this.placedObjects[i];
            if (p.type !== type) {
                continue;
            }
            var m = tpl.clone();
            this.orientClone(m, type);
            this.animateClone(tpl, m);
            m.position.set(p.x, y, p.z);
            if (type === 'lamp') {
                this.addLampLight(m);
            }
            this.setShadow(m, true);
            this.scene.add(m);
            this.addPickProxy(m, this.modelScale(type));
            this.registerSceneEditable('placed:' + p.id, this.propLabel(type),
                m, p.x, y, p.z, type === 'lamp' || type === 'av', this.modelScale(type));
            this.instanceClone(tpl, m);
        }
    };

    /**
     * Draw a placed copy of a prop model through its model's shared instanced
     * batch instead of with its own meshes (one draw per model part for every
     * copy, not one per copy). The clone stays in the scene as the editable,
     * pickable, deletable object - its meshes are just hidden, and each frame
     * updatePropInstances copies their world matrices into the batch, so moves,
     * rotations, scale edits and traffic motion all follow. Animated or skinned
     * copies are left drawing themselves (their bones and mixers move their own
     * nodes), as is any copy whose materials no longer match the model's.
     *
     * @param {Object} tpl The model template the copy was cloned from.
     * @param {Object} clone The placed copy (already in the scene).
     */
