        // tracked, so never cull the batch as a whole.
        mesh.frustumCulled = false;
        mesh.castShadow = batch.cast;
        mesh.receiveShadow = true;
        mesh.raycast = function() {
            return; // Picking hits the hidden copies (and their proxies) instead.
        };
