        this.calibTime = 1.5; // Seconds of normal stance that set the neutral.
        this.liftDead = -0.5; // Wrist height (widths above shoulders) to start engaging forward.
        this.liftFull = -0.1; // Wrist height for full forward engagement.
        this.climbStart = 0.2; // Wrist height where the dial starts blending into a climb.
        this.climbFull = 1.0; // Wrist height (arms overhead) for a pure climb.
        this.reverseClose = 0.35; // Hand-to-middle distance (widths) to start reversing.
        this.reverseFull = 0.12; // Hand-to-middle distance for full reverse.
        this.reverseLiftGate = 0.2; // Reverse only when the arms are not raised (lift below this).
        this.turnDead = 0.12; // Shoulder twist ignored.
        this.turnFull = 0.5; // Shoulder twist for full steering.
        this.crossHold = 0.5; // Seconds arms must stay crossed to pause/resume.
        this.switchRatio = 1.25; // How much closer someone else must look ...
        this.switchTime = 1.0; // ... and for how long, to take over.
        this.matchRadius = 0.25; // How far the followed person may move per frame.
        this.forgetTime = 1.0; // Seconds out of view before the presenter is forgotten.
        this.pointRangeX = 1.5; // Hand offset from the body's middle (x width) to a screen edge.
        this.pointCentreY = 0.6; // Hand height above the shoulders (x width) = screen middle.
        this.pointRangeY = 0.6; // Hand height change (x width) to the top or bottom edge.
        this.pointEase = 0.35; // Legacy fixed pointer smoothing (kept for reference).
        // Adaptive pointer smoothing: damp hard when the hand is nearly still
        // (kills landmark jitter so the dot does not waver), ease faster the
        // further the hand has genuinely moved (so it stays responsive).
        this.pointDead = 0.02; // Hand movement (screen fraction) treated as jitter.
        this.pointSpan = 0.3; // Movement for the fastest easing.
        this.pointEaseMin = 0.06; // Easing at/below the jitter radius (heavy damping).
        this.pointEaseMax = 0.5; // Easing at/above pointSpan (responsive).
